pragma solidity ^0.8.10;
interface I {function allowed(uint8 who) external pure returns(bool);}
contract B {enum E {A,B} function allowed(E) public pure virtual returns(bool){return false;}}
contract M is B {function allowed(E) public pure override returns(bool){return true;}}
contract C {I m; uint public value;constructor(address a){m=I(a);}function act() external {require(m.allowed(2));value=1;}}

pragma solidity ^0.8.10;
interface I {enum E {A,B} function allowed() external pure returns(E);}
contract B {function allowed() public pure virtual returns(uint8){return 0;}}
contract M is B {function allowed() public pure override returns(uint8){return 2;}}
contract C {I m;uint public value;constructor(address a){m=I(a);}function act() external {require(uint8(m.allowed())==2);value=1;}}

pragma solidity ^0.8.10;
contract B {function allowed(uint8) public pure virtual returns(bool){return false;}}
contract M is B {function allowed(uint8) public pure override returns(bool){return true;}}
contract C {address m;uint public value;constructor(address a){m=a;}function act() external {
(bool ok,bytes memory data)=m.staticcall(abi.encodeWithSignature("allowed(uint8)",uint256(256)));
require(ok);require(abi.decode(data,(bool)));value=1;}}

pragma solidity ^0.8.10;
contract M {function allowed(address who) external pure returns(bool){if(who != address(0)){assembly{mstore(0,1) revert(0,32)}} return false;}}
contract C {address m;uint public value;constructor(address a){m=a;}
function act() external { (,bytes memory data)=m.staticcall(abi.encodeWithSignature("allowed(address)",msg.sender)); require(abi.decode(data,(bool)));value=1;}
function failOnly() external { (bool ok,bytes memory data)=m.staticcall(abi.encodeWithSignature("allowed(address)",msg.sender)); require(!ok);require(abi.decode(data,(bool)));value=1;}}

pragma solidity ^0.8.10;
interface I {enum E {A,B} struct R {E e;} function allowed() external pure returns(R memory);}
contract M {struct R {uint8 e;} function allowed() external pure returns(R memory){return R(2);}}
contract C {I m;uint value;constructor(address a){m=I(a);}function act() external {require(uint8(m.allowed().e)==2);value=1;}}

pragma solidity ^0.8.10;
interface I {function allowed(uint8[] memory x) external pure returns(bool);}
contract M {enum E {A,B} function allowed(E[] memory) external pure returns(bool){return true;}}
contract C {I m;uint value;constructor(address a){m=I(a);}function act() external {uint8[] memory x=new uint8[](1);x[0]=2;require(m.allowed(x));value=1;}}

pragma solidity ^0.8.10;
interface I {struct S {uint a;uint b;} function allowed(S memory x) external pure returns(bool);}
contract M {struct S {uint b;uint a;} function allowed(S memory x) external pure returns(bool){return x.b==1;}}
contract C {I m;uint value;constructor(address a){m=I(a);}function act() external {require(m.allowed(I.S(0,1)));value=1;}}

pragma solidity ^0.8.10;
interface I {function allowed() external pure returns(uint8);}
contract B {function allowed() public pure virtual returns(uint8){return 0;}}
contract M is B {function allowed() public pure override returns(uint8 x){assembly{x:=256}}}
contract C {I m;uint public value;constructor(address a){m=I(a);}function act() external {require(m.allowed()!=0);value=1;}}

pragma solidity ^0.8.10;
interface I {struct S {uint8 x;} function allowed(S memory s) external pure returns(bool);}
contract B is I {function allowed(S memory) public pure virtual override returns(bool){return false;}}
contract M is B {function allowed(S memory s) public pure override returns(bool){return s.x!=0;}}
contract C {I m;uint public value;constructor(address a){m=I(a);}function act() external {uint8 x;assembly{x:=256}require(m.allowed(I.S(x)));value=1;}}

pragma solidity ^0.8.10;
interface I {function allowed(uint8 x) external pure returns(bool);}
contract B is I {function allowed(uint8) public pure virtual override returns(bool){return false;}}
contract M is B {function allowed(uint8 x) public pure override returns(bool){return x>255;}}
contract C {I m;uint public value;constructor(address a){m=I(a);}function act() external {uint8 x;assembly{x:=caller()}require(m.allowed(x));value=1;}}
